async () => {
  const w = document.querySelector('iframe').contentWindow;
  const app = w.pc.Application.getApplication();
  const st = w.ConfiguratorAPI.getSelectTool();
  const sinks = [];
  app.root.forEach((e) => { if (/sink_?point$/i.test(e.name) && e.enabled) sinks.push(e); });
  if (!sinks.length) return { err: 'no sink point' };
  const ren = []; sinks[0].forEach((e) => { if (e.enabled && e.render?.enabled) ren.push(e); });
  const pick = ren[0] || sinks[0];
  st.setSelected([pick]);
  await new Promise((r) => setTimeout(r, 800));
  const info = JSON.parse(JSON.stringify(w.ConfiguratorAPI.getSelectionInfo() || []));
  const pid = (Array.isArray(info) ? info[0] : info)?.productId;
  const cfg = pid ? await w.ConfiguratorAPI.getConfig(pid) : null;
  const pickCfg = (c) => c && Object.fromEntries(Object.entries(c.config ?? c).filter(([k]) => /sink|vessel|countertop/i.test(k)));
  return { sinkPoints: sinks.map((s) => s.name), picked: pick.name, info, productId: pid, config: pickCfg(cfg) };
}

async () => {
  const w = document.querySelector('iframe').contentWindow;
  const app = w.pc.Application.getApplication();
  const sinks = []; app.root.forEach((e) => { if (/sink_?point$/i.test(e.name)) sinks.push({ name: e.name, enabled: e.enabled, children: e.children.map((c) => c.name + (c.enabled ? '' : '(off)')).slice(0, 6) }); });
  const info = JSON.parse(JSON.stringify(w.ConfiguratorAPI.getSelectionInfo() || []));
  const pid = (window.__qaVesselPid || null);
  const cfg = pid ? await w.ConfiguratorAPI.getConfig(pid) : null;
  const c = cfg && (cfg.config ?? cfg);
  const menu = [...document.querySelectorAll('button,[role=menuitem],li')].filter((e) => { const r = e.getBoundingClientRect(); return r.width > 0 && r.left < innerWidth * 0.62; }).map((e) => (e.innerText || '').trim()).filter((t) => /^(Style|Color|Delete)$/.test(t));
  const logs = (window.__configuratorApiLogs || []).slice(-6).map((l) => JSON.stringify(l).slice(0, 300));
  return { sinks, selection: info, config: c && Object.fromEntries(Object.entries(c).filter(([k]) => /sink|vessel|countertop/i.test(k))), menu, price: (document.body.innerText.match(/Total List Price\s*\$[\d,.]+/) || [''])[0], apiLogs: logs, apiLoggerInstalled: !!window.__configuratorApiLoggerInstalled };
}

